                  <div key={task.id} className={`bg-white p-2 rounded-lg border border-indigo-100 shadow-sm flex items-center gap-3 relative overflow-hidden animate-fadeIn transition-opacity ${isQueuePaused && task.status === 'pending' ? 'opacity-50' : 'opacity-100'}`}>
