import React, { Component, ReactNode } from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { hasError: false, error: null };

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center min-h-screen bg-slate-50 p-6 text-center font-sans">
            <div className="w-20 h-20 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-6 shadow-xl shadow-red-100">
                <i className="fa-solid fa-bug text-3xl"></i>
            </div>
            <h1 className="text-xl font-bold text-slate-800 mb-2">應用程式發生錯誤</h1>
            <p className="text-sm text-slate-500 mb-8 max-w-xs mx-auto leading-relaxed">
               很抱歉，處理過程中發生了預期外的狀況。請嘗試重新載入頁面。
            </p>
            <div className="bg-white p-4 rounded-xl border border-slate-200 w-full max-w-sm mb-6 shadow-sm">
                <p className="text-[10px] text-slate-400 font-mono break-all text-left">
                    {this.state.error?.message || "Unknown Error"}
                </p>
            </div>
            <button onClick={() => window.location.reload()} className="px-8 py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 active:scale-95 transition-transform">
                重新載入頁面
            </button>
        </div>
      );
    }

    return this.props.children;
  }
}

const rootElement = document.getElementById('root');
if (!rootElement) {
  console.error("Critical: Root element not found");
} else {
  try {
    const root = ReactDOM.createRoot(rootElement);
    root.render(
      <React.StrictMode>
        <ErrorBoundary>
            <App />
        </ErrorBoundary>
      </React.StrictMode>
    );
  } catch (err: any) {
    const errorOverlay = document.getElementById('error-overlay');
    const errorMsg = document.getElementById('error-msg');
    if (errorOverlay && errorMsg) {
      errorOverlay.style.display = 'flex';
      errorMsg.innerText = "React Mount Error: " + err.message;
    }
  }
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo, detectBusinessCards } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as pdfjsLib from 'pdfjs-dist';

// Config PDF.js worker
const pdfjs = (pdfjsLib as any).default || pdfjsLib;
if (pdfjs.GlobalWorkerOptions) {
    // Use cdnjs for reliable worker loading in production environments
    pdfjs.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js`;
}

const DB_NAME = 'QSHubDB_V1_0';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 6);
      request.onupgradeneeded = (e: any) => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const deleteCardFromDB = async (id: string) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).delete(id);
  } catch (e) { console.warn("DB Delete Error", e); }
};

const clearAllCardsFromDB = async () => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).clear();
    return true;
  } catch (e) {
    console.warn("DB Clear Error", e);
    return false;
  }
};

const getCardsMetadataFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const items: BusinessCardData[] = [];
      const request = store.openCursor();
      request.onsuccess = (event: any) => {
        const cursor = event.target.result;
        if (cursor) {
          const { imageUrl, ...rest } = cursor.value;
          items.push(rest as BusinessCardData);
          cursor.continue();
        } else {
          resolve(items);
        }
      };
      request.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const getCardById = async (id: string): Promise<BusinessCardData | null> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.get(id);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch (e) { return null; }
};

/**
 * Image Compression Utility
 * Prevents OOM crashes on mobile by resizing large images before processing.
 */
const compressImage = (file: File | Blob, maxWidth = 1600, quality = 0.8): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        // Calculate new dimensions
        let w = img.width;
        let h = img.height;

        if (w > maxWidth || h > maxWidth) {
           const ratio = Math.min(maxWidth / w, maxWidth / h);
           w = Math.floor(w * ratio);
           h = Math.floor(h * ratio);
        }

        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(img, 0, 0, w, h);
            // Returns base64 string without prefix
            resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
        } else {
            reject(new Error("Canvas context creation failed"));
        }
      };
      img.onerror = (err) => reject(new Error("Image load failed"));
      img.src = e.target?.result as string;
    };
    reader.onerror = (err) => reject(new Error("File read failed"));
    reader.readAsDataURL(file);
  });
};

type ViewMode = 'camera' | 'file' | 'detail' | 'cropper';

interface CropRegion {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCardData, setSelectedCardData] = useState<BusinessCardData | null>(null);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [rotation, setRotation] = useState(0);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff'>('employer');
  const [isExporting, setIsExporting] = useState(false);
  const [isImageZoomed, setIsImageZoomed] = useState(false);
  const [isLoadingDetail, setIsLoadingDetail] = useState(false);
  const [isQueuePaused, setIsQueuePaused] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);
  const imgContainerRef = useRef<HTMLDivElement>(null);
  const [containerDim, setContainerDim] = useState({ w: 0, h: 0 });

  // Cropper States
  const [cropperImage, setCropperImage] = useState<string | null>(null);
  const [cropRegions, setCropRegions] = useState<CropRegion[]>([]);
  const [isDrawing, setIsDrawing] = useState(false);
  const [isMoving, setIsMoving] = useState(false);
  const [isResizing, setIsResizing] = useState<string | null>(null); 
  const [activeCropId, setActiveCropId] = useState<string | null>(null);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [initialRect, setInitialRect] = useState<CropRegion | null>(null);
  const [currentRect, setCurrentRect] = useState<CropRegion | null>(null);
  const cropperImgRef = useRef<HTMLImageElement>(null);
  const [pdfDoc, setPdfDoc] = useState<any>(null);
  const [currentPdfPage, setCurrentPdfPage] = useState(1);
  const [isRenderingPdf, setIsRenderingPdf] = useState(false);
  const [isAiDetecting, setIsAiDetecting] = useState(false);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    const loadInitialData = async () => {
      const savedCards = await getCardsMetadataFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
      }
    };
    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    setRotation(0);
    if (selectedCardId) {
      setIsLoadingDetail(true);
      setSelectedCardData(null); 
      getCardById(selectedCardId).then(data => {
        if (data) setSelectedCardData(data);
        setIsLoadingDetail(false);
      }).catch(() => setIsLoadingDetail(false));
    } else {
      setSelectedCardData(null);
    }
  }, [selectedCardId]);

  useEffect(() => {
    if (viewMode === 'detail' && imgContainerRef.current) {
        const updateDim = () => {
            if (imgContainerRef.current) {
                const { width, height } = imgContainerRef.current.getBoundingClientRect();
                if (width > 0 && height > 0) {
                    setContainerDim({ w: width, h: height });
                }
            }
        };

        updateDim();
        const timers = [
            setTimeout(updateDim, 50),
            setTimeout(updateDim, 150),
            setTimeout(updateDim, 350),
            setTimeout(updateDim, 600)
        ];

        const ro = new ResizeObserver(() => {
             requestAnimationFrame(updateDim);
        });
        ro.observe(imgContainerRef.current);

        return () => {
            ro.disconnect();
            timers.forEach(clearTimeout);
        };
    }
  }, [viewMode, selectedCardData]);

  const handleDeleteCard = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!window.confirm("確定要刪除這筆名片資料嗎？此動作無法復原。")) return;

    await deleteCardFromDB(id);
    setCards(prev => prev.filter(c => c.id !== id));
    if (selectedCardId === id) {
      setSelectedCardId(null);
      setSelectedCardData(null);
      setViewMode('file');
    }
  };

  const handleClearAll = async () => {
    if (cards.length === 0) return;
    if (!window.confirm("⚠️ 警告：這將會永久刪除所有類別（Employer, Academic, Staff）的所有名片紀錄！確定要執行嗎？")) return;

    const success = await clearAllCardsFromDB();
    if (success) {
      setCards([]);
      setSelectedCardId(null);
      setSelectedCardData(null);
      setViewMode('file');
      alert("已清空所有紀錄");
    }
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));
    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File missing");

      const base64Data = await compressImage(fileObj);
      const info = await extractCardInfo(base64Data, 'image/jpeg');

      const newCard: BusinessCardData = {
        ...info,
        id: task.id, 
        scannedAt: Date.now(),
        source: 'QS Hub Scanner',
        imageUrl: `data:image/jpeg;base64,${base64Data}`,
      };

      await saveCardToDB(newCard);
      const { imageUrl, ...newCardMeta } = newCard;

      setCards(prev => [newCardMeta as BusinessCardData, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));

    } catch (err: any) {
      console.error("Task Error:", err);
      if (err.message === 'API_KEY_INVALID') window.aistudio?.openSelectKey();
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "處理失敗" } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing && !isQueuePaused) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask({...nextTask}); 
    }
  }, [tasks, isProcessing, isQueuePaused]); 

  const formatCardToText = (card: BusinessCardData): string => {
    return `【QS Hub 掃描資料】\n` +
           `類別: ${card.category.toUpperCase()}\n` +
           `姓名: ${card.prefix ? card.prefix + ' ' : ''}${card.firstName} ${card.lastName}\n` +
           `職稱: ${card.title}\n` +
           `公司: ${card.company}\n` +
           (card.department ? `部門: ${card.department}\n` : '') +
           (card.email ? `Email: ${card.email}\n` : '') +
           (card.phone ? `電話: ${card.phone}\n` : '') +
           (card.country ? `國家: ${card.country}\n` : '') +
           (card.website ? `網站: ${card.website}\n` : '') +
           (card.address ? `地址: ${card.address}\n` : '');
  };

  const createExcelFile = async (targetCards: BusinessCardData[], fileName: string, mode: 'qs' | 'full'): Promise<File> => {
    const XLSX = await import('xlsx');
    let exportData: any[];

    if (mode === 'full') {
      exportData = targetCards.map(c => ({
        'ID': c.id,
        '來源 (Source)': c.source || 'QS Hub Scanner',
        '類別 (Category)': c.category,
        '掃描時間': new Date(c.scannedAt).toLocaleString(),
        '稱謂 (Title/Prefix)': c.prefix || '',
        '姓氏 (Last Name)': c.lastName || '',
        '名字 (First Name)': c.firstName || '',
        '職稱 (Job Title)': c.title || '',
        '公司/機構 (Company)': c.company || '',
        '部門 (Department)': c.department || '',
        '產業 (Industry)': c.industry || '',
        '學科 (Subject)': c.subject || '',
        '電子郵件 (Email)': c.email || '',
        '電話 (Phone)': c.phone || '',
        '國家/地區 (Country)': c.country || '',
        '網站 (Website)': c.website || '',
        '地址 (Address)': c.address || '',
        '備註 (Notes)': c.notes || ''
      }));
    } else {
      exportData = targetCards.map(c => {
        if (c.category === 'academic') {
          return {
            'Source': c.source || 'QS Hub Scanner',
            'Title': c.prefix || '',
            'First Name': c.firstName || '',
            'Last Name': c.lastName || '',
            'Job Title': c.title || '',
            'Department': c.department || '',
            'Institution': c.company || '',
            'Country or Territory': c.country || '',
            'Email': c.email || '',
            'Subject': c.subject || '',
            'Phone (Optional)': c.phone || ''
          };
        } else {
          return {
            'Source': c.source || 'QS Hub Scanner',
            'Title': c.prefix || '',
            'First Name': c.firstName || '',
            'Last Name': c.lastName || '',
            'Position': c.title || '',
            'Industry': c.industry || '',
            'Company Name': c.company || '',
            'Country or Territory': c.country || '',
            'Email': c.email || '',
            'Phone (Optional)': c.phone || ''
          };
        }
      });
    }

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "QS_Data");
    const excelBuffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    return new File([blob], fileName, { type: blob.type });
  };

  const triggerDownload = (file: File) => {
    const url = URL.createObjectURL(file);
    const a = document.createElement('a');
    a.href = url;
    a.download = file.name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleShareOrExport = async (targetCategory: 'employer' | 'academic' | 'staff' | 'all', mode: 'qs' | 'full') => {
    const targetCards = targetCategory === 'all' ? cards : cards.filter(c => c.category === targetCategory);
    if (targetCards.length === 0) return;

    setIsExporting(true);
    try {
      const timestamp = new Date().toISOString().split('T')[0];
      const prefix = mode === 'qs' ? 'QS_Format' : 'Full_Data';
      const fileName = `${prefix}_${targetCategory}_${timestamp}.xlsx`;

      if (isMobile) {
        if (mode === 'full') {
          const text = targetCards.map(c => formatCardToText(c)).join('\n---\n');
          if (navigator.share) {
             try {
               await navigator.share({ title: 'QS Hub 完整資料', text });
               return;
             } catch(e) {
               console.warn("Text share failed, falling back to file...", e);
             }
          }
        } 

        const excelFile = await createExcelFile(targetCards, fileName, mode);

        if (navigator.canShare && navigator.canShare({ files: [excelFile] })) {
            try {
              await navigator.share({ files: [excelFile], title: mode === 'qs' ? 'QS 格式 Excel' : '完整名片資料' });
              return;
            } catch (shareError: any) {
              console.warn("Share failed, falling back to download:", shareError);
              triggerDownload(excelFile);
            }
        } else {
            triggerDownload(excelFile);
        }
        return;
      }

      const excelFile = await createExcelFile(targetCards, fileName, mode);
      triggerDownload(excelFile);

    } catch (err: any) { 
      alert("匯出失敗：" + err.message); 
    } finally { 
      setIsExporting(false); 
    }
  };

  const handleShareCardExcel = async (card: BusinessCardData, mode: 'qs' | 'full') => {
    setIsExporting(true);
    try {
      const prefix = mode === 'qs' ? 'QS_Format' : 'Full_Data';
      const fileName = `${prefix}_${card.lastName}_${card.firstName}.xlsx`;
      const excelFile = await createExcelFile([card], fileName, mode);

      if (isMobile) {
        if (navigator.canShare && navigator.canShare({ files: [excelFile] })) {
           try {
             await navigator.share({ files: [excelFile], title: `${card.firstName} ${card.lastName}` });
             return;
           } catch (shareError) {
             console.warn("Share failed, falling back to download:", shareError);
             triggerDownload(excelFile);
           }
        } else {
           triggerDownload(excelFile);
        }
        return;
      }
      triggerDownload(excelFile);
    } catch (e) {
      console.warn("Export failed", e);
      alert("分享失敗，請重試");
    } finally {
      setIsExporting(false);
    }
  };

  const autoDetectInCropper = async (b64: string) => {
    setIsAiDetecting(true);
    try {
      const boxes = await detectBusinessCards(b64);
      const regions: CropRegion[] = boxes.map(box => ({
        id: crypto.randomUUID(),
        x: (box.xmin / 1000) * 100,
        y: (box.ymin / 1000) * 100,
        w: ((box.xmax - box.xmin) / 1000) * 100,
        h: ((box.ymax - box.ymin) / 1000) * 100
      }));
      setCropRegions(regions);
    } catch (e) { console.warn(e); } 
    finally { setIsAiDetecting(false); }
  };

  const renderPdfPage = async (pdf: any, pageNum: number) => {
    setIsRenderingPdf(true);
    try {
        const page = await pdf.getPage(pageNum);
        const scale = 2;
        const viewport = page.getViewport({ scale });
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        canvas.height = viewport.height;
        canvas.width = viewport.width;

        if (context) {
            await page.render({ canvasContext: context, viewport }).promise;
            const b64 = canvas.toDataURL('image/jpeg');
            setCropperImage(b64);
            setCropRegions([]);
            autoDetectInCropper(b64.split(',')[1]);
        }
    } catch (e) { alert("無法讀取 PDF 頁面"); } 
    finally { setIsRenderingPdf(false); }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const firstFile = files[0];
    if (firstFile.type === 'application/pdf') {
        const reader = new FileReader();
        reader.onload = async (ev) => {
            const typedarray = new Uint8Array(ev.target?.result as ArrayBuffer);
            try {
                const pdf = await pdfjs.getDocument(typedarray).promise;
                setPdfDoc(pdf);
                setCurrentPdfPage(1);
                await renderPdfPage(pdf, 1);
                setViewMode('cropper');
            } catch (err) { console.error(err); alert("PDF 解析失敗"); }
        };
        reader.readAsArrayBuffer(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    if (files.length === 1) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const b64 = event.target?.result as string;
            setCropperImage(b64);
            setCropRegions([]);
            setViewMode('cropper');
            autoDetectInCropper(b64.split(',')[1]);
        };
        reader.readAsDataURL(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    const newTasks: ProcessingTask[] = [];
    for (const f of Array.from(files) as File[]) {
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);
      const previewUrl = URL.createObjectURL(f);
      newTasks.push({ id, fileName: f.name, status: 'pending', progress: 0, batchIndex: 1, previewUrl });
    }
    setTasks(prev => [...prev, ...newTasks]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const getMousePos = (e: React.MouseEvent | React.TouchEvent) => {
    if (!cropperImgRef.current) return { x: 0, y: 0 };
    const rect = cropperImgRef.current.getBoundingClientRect();
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;
    return {
      x: ((clientX - rect.left) / rect.width) * 100,
      y: ((clientY - rect.top) / rect.height) * 100
    };
  };

  const handleCropStart = (e: React.MouseEvent | React.TouchEvent, action: 'draw' | 'move' | 'resize' = 'draw', cropId?: string, handle?: string) => {
    const pos = getMousePos(e);
    setStartPos(pos);
    if (action === 'draw') {
        setCurrentRect({ id: 'temp', x: pos.x, y: pos.y, w: 0, h: 0 });
        setIsDrawing(true);
        setActiveCropId(null);
    } else if (action === 'move' && cropId) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsMoving(true); setActiveCropId(cropId); }
    } else if (action === 'resize' && cropId && handle) {
        const crop = cropRegions.find(r => r.id === cropId);
        if (crop) { setInitialRect({ ...crop }); setIsResizing(handle); setActiveCropId(cropId); }
    }
  };

  const handleCropMove = (e: React.MouseEvent | React.TouchEvent) => {
    const pos = getMousePos(e);
    if (isDrawing && currentRect) {
        setCurrentRect({ ...currentRect, x: Math.min(pos.x, startPos.x), y: Math.min(pos.y, startPos.y), w: Math.abs(pos.x - startPos.x), h: Math.abs(pos.y - startPos.y) });
    } else if (isMoving && activeCropId && initialRect) {
        setCropRegions(prev => prev.map(r => r.id === activeCropId ? { ...r, x: Math.max(0, Math.min(100 - r.w, initialRect.x + (pos.x - startPos.x))), y: Math.max(0, Math.min(100 - r.h, initialRect.y + (pos.y - startPos.y))) } : r));
    } else if (isResizing && activeCropId && initialRect) {
        const dx = pos.x - startPos.x; const dy = pos.y - startPos.y;
        setCropRegions(prev => prev.map(r => {
            if (r.id !== activeCropId) return r;
            let { x, y, w, h } = initialRect;
            if (isResizing.includes('t')) { const newY = Math.max(0, y + dy); h = h + (y - newY); y = newY; }
            if (isResizing.includes('b')) { h = Math.max(1, Math.min(100 - y, h + dy)); }
            if (isResizing.includes('l')) { const newX = Math.max(0, x + dx); w = w + (x - newX); x = newX; }
            if (isResizing.includes('r')) { w = Math.max(1, Math.min(100 - x, w + dx)); }
            return { ...r, x, y, w, h };
        }));
    }
  };

  const handleCropEnd = () => {
    if (isDrawing && currentRect && currentRect.w > 2 && currentRect.h > 2) {
        const newCrop = { ...currentRect, id: crypto.randomUUID() };
        setCropRegions(prev => [...prev, newCrop]);
        setActiveCropId(newCrop.id);
    }
    setIsDrawing(false); setIsMoving(false); setIsResizing(null); setCurrentRect(null);
  };

  const processCrops = async () => {
    if (!cropperImage || !cropperImgRef.current) return;
    const sourceImg = new Image();
    sourceImg.src = cropperImage;
    await new Promise(r => sourceImg.onload = r);
    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < cropRegions.length; i++) {
        const crop = cropRegions[i];
        const canvas = document.createElement('canvas');
        const rX = (crop.x / 100) * sourceImg.naturalWidth; const rY = (crop.y / 100) * sourceImg.naturalHeight;
        const rW = (crop.w / 100) * sourceImg.naturalWidth; const rH = (crop.h / 100) * sourceImg.naturalHeight;
        canvas.width = rW; canvas.height = rH;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(sourceImg, rX, rY, rW, rH, 0, 0, rW, rH);
            const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/jpeg', 0.95));
            if (blob) {
                const id = crypto.randomUUID(); filesMap.current.set(id, blob);
                newTasks.push({ id, fileName: `CROP_${i+1}.jpg`, status: 'pending', progress: 0, batchIndex: 1, previewUrl: URL.createObjectURL(blob) });
            }
        }
    }
    setTasks(prev => [...prev, ...newTasks]); 
    setPdfDoc(null); setCropperImage(null); 
    setViewMode('file'); 
  };

  const visibleCards = useMemo(() => cards.filter(c => c.category === activeCategory), [cards, activeCategory]);
  const activeTasks = useMemo(() => tasks.filter(t => t.status === 'pending' || t.status === 'processing' || t.status === 'error'), [tasks]);

  const handleNextCard = () => {
    if (!selectedCardId || visibleCards.length <= 1) return;
    const currentIndex = visibleCards.findIndex(c => c.id === selectedCardId);
    if (currentIndex >= 0 && currentIndex < visibleCards.length - 1) {
      setSelectedCardId(visibleCards[currentIndex + 1].id);
    }
  };

  const handlePrevCard = () => {
    if (!selectedCardId || visibleCards.length <= 1) return;
    const currentIndex = visibleCards.findIndex(c => c.id === selectedCardId);
    if (currentIndex > 0) {
      setSelectedCardId(visibleCards[currentIndex - 1].id);
    }
  };

  const currentCardIndex = selectedCardId ? visibleCards.findIndex(c => c.id === selectedCardId) : -1;

  // View Logic for Mobile vs Desktop
  const showDashboard = !isMobile || viewMode === 'file';
  const showMain = !isMobile || viewMode !== 'file';

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900 font-sans">
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf" multiple onChange={handleFileUpload} />

      {showDashboard && (
        <aside className={`${isMobile ? 'w-full' : 'w-[320px] border-r border-slate-200'} h-full flex flex-col bg-white shadow-xl lg:shadow-none z-10`}>
           <div className="px-5 pt-6 pb-4 bg-white shrink-0 z-10 sticky top-0 border-b border-slate-100" style={{ paddingTop: 'calc(1.5rem + var(--sat))' }}>
              <div className="flex items-center justify-between mb-5">
                 <div className="flex items-center gap-3">
                    <div className="w-9 h-9 bg-gradient-to-br from-indigo-600 to-indigo-700 rounded-xl flex items-center justify-center text-white shadow-md shadow-indigo-200">
                       <i className="fa-solid fa-bahai text-base animate-[spin_10s_linear_infinite]"></i>
                    </div>
                    <div>
                       <h1 className="text-sm font-black text-slate-900 leading-none">QS HUB</h1>
                       <div className="text-[9px] font-bold text-slate-400 tracking-wider mt-0.5">SCANNER PRO</div>
                    </div>
                 </div>
                 <div className="flex items-center gap-2">
                     {window.aistudio && (
                       <button onClick={() => window.aistudio.openSelectKey()} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 flex items-center justify-center transition-colors">
                          <i className="fa-solid fa-key text-xs"></i>
                       </button>
                     )}
                     <button 
                       onClick={handleClearAll} 
                       disabled={cards.length === 0}
                       className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-red-500 hover:bg-red-50 flex items-center justify-center transition-colors disabled:opacity-30"
                       title="清空紀錄"
                     >
                       <i className="fa-solid fa-trash-can text-xs"></i>
                     </button>
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-3 mb-5">
                 <button onClick={() => isMobile ? setViewMode('camera') : fileInputRef.current?.click()} className="flex flex-col items-center justify-center p-3.5 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-200 active:scale-95 transition-transform group">
                    <i className="fa-solid fa-camera text-xl mb-1 group-hover:scale-110 transition-transform"></i>
                    <span className="text-[10px] font-bold uppercase tracking-wide">拍照掃描</span>
                 </button>
                 <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center p-3.5 bg-white border border-slate-200 text-slate-600 rounded-xl active:scale-95 transition-transform hover:bg-slate-50 hover:border-indigo-200 group">
                    <i className="fa-solid fa-cloud-arrow-up text-xl mb-1 group-hover:text-indigo-500 transition-colors"></i>
                    <span className="text-[10px] font-bold uppercase tracking-wide">匯入檔案</span>
                 </button>
              </div>

              <div className="flex p-1 bg-slate-100/80 rounded-lg mb-3">
                 <CompactTab label="Employer" active={activeCategory === 'employer'} count={cards.filter(c=>c.category==='employer').length} onClick={() => setActiveCategory('employer')} />
                 <CompactTab label="Academic" active={activeCategory === 'academic'} count={cards.filter(c=>c.category==='academic').length} onClick={() => setActiveCategory('academic')} />
                 <CompactTab label="Staff" active={activeCategory === 'staff'} count={cards.filter(c=>c.category==='staff').length} onClick={() => setActiveCategory('staff')} />
              </div>

              <div className="flex gap-2">
                 <button onClick={() => handleShareOrExport(activeCategory, 'qs')} disabled={isExporting} className="flex-1 py-2.5 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-lg text-[10px] font-bold uppercase tracking-wide flex items-center justify-center gap-2 active:scale-95 transition-transform disabled:opacity-50">
                    {isExporting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : <i className="fa-solid fa-file-excel"></i>} 分享 Excel
                 </button>
                 <button onClick={() => handleShareOrExport('all', 'full')} disabled={isExporting} className="flex-1 py-2.5 bg-white border border-slate-200 text-slate-600 rounded-lg text-[10px] font-bold uppercase tracking-wide flex items-center justify-center gap-2 active:scale-95 transition-transform disabled:opacity-50">
                    {isExporting ? <i className="fa-solid fa-circle-notch fa-spin"></i> : <i className="fa-solid fa-file-export"></i>} 分享完整
                 </button>
              </div>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar p-2 bg-slate-50/50 pb-20 lg:pb-3 flex flex-col">
              {activeTasks.length > 0 && (
                <div className="mb-2 px-1 shrink-0 max-h-[150px] overflow-y-auto custom-scrollbar border-b border-slate-200 pb-2">
                  <div className="flex items-center justify-between px-1 mb-1.5">
                    <div className="text-[9px] font-bold text-indigo-500 uppercase tracking-widest flex items-center">
                       <i className={`fa-solid fa-circle-notch ${isProcessing && !isQueuePaused ? 'fa-spin' : ''} mr-1`}></i> 
                       處理佇列 ({activeTasks.length})
                    </div>
                    <button 
                       onClick={() => setIsQueuePaused(!isQueuePaused)}
                       className={`w-5 h-5 rounded flex items-center justify-center transition-colors ${isQueuePaused ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-200 text-slate-500 hover:bg-slate-300'}`}
                    >
                       <i className={`fa-solid ${isQueuePaused ? 'fa-play' : 'fa-pause'} text-[9px]`}></i>
                    </button>
                  </div>
                  {activeTasks.map(task => (
                     <div key={task.id} className="bg-white p-1.5 rounded-lg border border-indigo-100 shadow-sm flex items-center gap-2 relative overflow-hidden mb-1.5">
                         {task.status === 'processing' && !isQueuePaused && <div className="absolute bottom-0 left-0 h-0.5 bg-indigo-500 animate-[loading_1s_ease-in-out_infinite]" style={{width: '100%'}}></div>}
                         <div className="w-8 h-8 shrink-0 bg-slate-100 rounded flex items-center justify-center overflow-hidden border border-slate-200">
                            {task.previewUrl ? <img src={task.previewUrl} className="w-full h-full object-cover opacity-90" /> : <i className="fa-solid fa-file text-slate-400 text-xs"></i>}
                         </div>
                         <div className="flex-1 min-w-0">
                            <div className="text-[9px] font-bold text-slate-700 truncate">{task.fileName}</div>
                            <div className="text-[8px] text-slate-400 font-medium truncate">
                              {task.status === 'pending' && (isQueuePaused ? '已暫停' : '等待中...')}
                              {task.status === 'processing' && <span className="text-indigo-500">AI 分析中...</span>}
                              {task.status === 'error' && <span className="text-red-500">{task.error || '失敗'}</span>}
                            </div>
                         </div>
                         {task.status === 'error' && (
                           <button onClick={(e) => {e.stopPropagation(); setTasks(prev => prev.filter(t => t.id !== task.id))}} className="w-5 h-5 flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-full"><i className="fa-solid fa-xmark text-[10px]"></i></button>
                         )}
                     </div>
                  ))}
                </div>
              )}

              <div className="grid grid-cols-2 lg:grid-cols-1 gap-2 pb-10 px-1 content-start">
                {visibleCards.length === 0 ? (
                   <div className="col-span-2 lg:col-span-1 flex flex-col items-center justify-center py-16 text-slate-300">
                     <i className="fa-regular fa-folder-open text-4xl mb-3 opacity-30"></i>
                     <span className="text-xs font-medium">尚無資料</span>
                     <p className="text-[10px] mt-1 opacity-60">請點擊上方按鈕開始掃描</p>
                   </div>
                ) : (
                   visibleCards.map(c => (
                     <div key={c.id} onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); }} className={`group relative p-3 rounded-xl cursor-pointer transition-all duration-200 border flex flex-col items-center text-center gap-2 active:scale-[0.98] ${selectedCardId === c.id && !isMobile ? 'bg-white border-indigo-500 shadow-lg shadow-indigo-100' : 'bg-white border-slate-200/60 hover:border-slate-300 shadow-sm'}`}>
                       <button 
                         onClick={(e) => handleDeleteCard(e, c.id)}
                         className="absolute top-2 right-2 w-6 h-6 bg-red-50 text-red-500 rounded-full opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center hover:bg-red-500 hover:text-white"
                       >
                         <i className="fa-solid fa-trash-can text-[10px]"></i>
                       </button>
                       <div className="w-10 h-10 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center text-sm font-bold shrink-0">{c.lastName.charAt(0)}{c.firstName.charAt(0)}</div>
                       <div className="w-full min-w-0">
                         <div className="font-bold text-[13px] mb-0.5 tracking-tight truncate text-slate-800">{c.firstName} {c.lastName}</div>
                         <div className="text-[10px] font-medium text-slate-400 truncate uppercase tracking-wide">{c.company}</div>
                       </div>
                     </div>
                  ))
                )}
              </div>
           </div>
        </aside>
      )}

      {showMain && (
        <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative h-full overflow-hidden" style={{ paddingTop: isMobile ? 'env(safe-area-inset-top)' : 0 }}>
          <div className="flex-1 relative overflow-hidden">
            {viewMode === 'camera' && (
              <div className="h-full p-4 lg:p-8 animate-fadeIn relative flex flex-col">
                {isMobile && <button onClick={() => setViewMode('file')} className="absolute top-4 left-4 z-50 w-10 h-10 bg-white/20 backdrop-blur text-white rounded-full flex items-center justify-center shadow-lg"><i className="fa-solid fa-arrow-left"></i></button>}
                <CameraScanner onCapture={async (b64) => { 
                    const id = crypto.randomUUID(); const res = await fetch(`data:image/jpeg;base64,${b64}`);
                    const blob = await res.blob(); filesMap.current.set(id, blob);
                    const previewUrl = URL.createObjectURL(blob);
                    setTasks(prev => [...prev, { id, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, previewUrl }]);
                    setViewMode('file'); 
                }} onClose={() => setViewMode('file')} />
              </div>
            )}

            {viewMode === 'file' && !isMobile && !selectedCardData && !cropperImage && (
              <div className="h-full flex flex-col items-center justify-center p-4 lg:p-10 animate-fadeInUp relative">
                <div className="w-full max-w-2xl p-8 lg:p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white/80 backdrop-blur-lg text-center group shadow-lg cursor-pointer transition-all hover:border-indigo-300 relative overflow-hidden" onClick={() => fileInputRef.current?.click()}>
                      <div className="w-20 h-20 lg:w-24 lg:h-24 bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-xl shadow-indigo-100 relative z-10 animate-float"><i className="fa-solid fa-print text-3xl text-white"></i></div>
                      <div className="relative z-10">
                          <h3 className="text-2xl lg:text-3xl font-extrabold text-slate-800 mb-3">匯入掃描檔案</h3>
                          <p className="text-slate-400 text-sm mb-10 max-w-sm mx-auto">支援 PDF, JPG, PNG 格式<br/><span className="text-indigo-500 font-bold"><i className="fa-solid fa-wand-magic-sparkles"></i> AI 自動定位名片位置</span></p>
                          <div className="inline-flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl text-sm font-bold uppercase tracking-widest shadow-lg group-hover:bg-indigo-700 transition-all">選擇檔案</div>
                      </div>
                </div>
              </div>
            )}

            {viewMode === 'cropper' && cropperImage && (
               <div className="h-full flex flex-col bg-slate-100 animate-fadeIn" onMouseMove={handleCropMove} onMouseUp={handleCropEnd} onTouchMove={handleCropMove} onTouchEnd={handleCropEnd}>
                  <div className="flex items-center justify-between p-4 bg-white border-b border-slate-200 shrink-0 z-[100]">
                      <div className="flex items-center gap-4">
                          <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center"><i className="fa-solid fa-crop-simple"></i></div>
                          <div className="hidden lg:block">
                              <h2 className="text-[15px] font-bold text-slate-800">智慧裁切工具</h2>
                              <p className="text-[10px] font-bold uppercase tracking-wider text-slate-400">已自動定位 {cropRegions.length} 張名片</p>
                          </div>
                      </div>
                      <div className="flex gap-2">
                          {isAiDetecting && <div className="flex items-center gap-2 px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-lg animate-pulse"><i className="fa-solid fa-wand-magic-sparkles fa-spin text-xs"></i><span className="text-[10px] font-bold uppercase hidden sm:inline">AI 偵測中...</span></div>}
                          {pdfDoc && (
                              <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
                                  <button disabled={currentPdfPage <= 1} onClick={() => { setCurrentPdfPage(p => p - 1); renderPdfPage(pdfDoc, currentPdfPage - 1); }} className="w-8 h-8 flex items-center justify-center rounded bg-white disabled:opacity-50"><i className="fa-solid fa-chevron-left text-xs"></i></button>
                                  <span className="text-xs font-bold w-12 text-center">{currentPdfPage}/{pdfDoc.numPages}</span>
                                  <button disabled={currentPdfPage >= pdfDoc.numPages} onClick={() => { setCurrentPdfPage(p => p + 1); renderPdfPage(pdfDoc, currentPdfPage + 1); }} className="w-8 h-8 flex items-center justify-center rounded bg-white disabled:opacity-50"><i className="fa-solid fa-chevron-right text-xs"></i></button>
                              </div>
                          )}
                          <button onClick={() => { setViewMode('file'); setCropperImage(null); setPdfDoc(null); }} className="px-4 py-2 text-xs font-bold text-slate-500 hover:bg-slate-100 rounded-lg">取消</button>
                          <button onClick={processCrops} disabled={cropRegions.length === 0} className="px-6 py-2 text-xs font-bold text-white bg-indigo-600 rounded-lg shadow-lg disabled:opacity-50 flex items-center gap-2">分析 <span className="hidden sm:inline">({cropRegions.length})</span></button>
                      </div>
                  </div>
                  <div className="flex-1 overflow-auto p-4 lg:p-12 flex items-start justify-center relative select-none bg-slate-200/50" onMouseDown={(e) => { if (e.target === e.currentTarget) handleCropStart(e, 'draw'); }}>
                      <div className="relative shadow-2xl bg-white">
                          {isRenderingPdf && <div className="absolute inset-0 bg-white/80 z-[60] flex items-center justify-center backdrop-blur-sm animate-fadeIn"><i className="fa-solid fa-circle-notch fa-spin text-3xl text-indigo-500"></i></div>}
                          <img ref={cropperImgRef} src={cropperImage} className="max-w-none w-auto h-auto block select-none pointer-events-none" style={{ maxHeight: 'calc(100vh - 180px)' }} draggable={false} />
                          <div className="absolute inset-0 z-10" onMouseDown={(e) => handleCropStart(e, 'draw')}></div>
                          {cropRegions.map(crop => (
                              <div key={crop.id} className={`absolute border-2 z-20 group ${activeCropId === crop.id ? 'border-indigo-500 bg-indigo-500/10' : 'border-emerald-400 bg-emerald-400/10 hover:border-indigo-400'}`} style={{ left: `${crop.x}%`, top: `${crop.y}%`, width: `${crop.w}%`, height: `${crop.h}%` }} onMouseDown={(e) => { e.stopPropagation(); handleCropStart(e, 'move', crop.id); }}>
                                  <button className="absolute -top-3 -right-3 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center text-[10px] shadow-lg z-40" onClick={(e) => { e.stopPropagation(); setCropRegions(prev => prev.filter(c => c.id !== crop.id)); }}><i className="fa-solid fa-xmark"></i></button>
                                  <div className="absolute top-1 left-1 pointer-events-none"><span className={`text-[8px] font-black uppercase px-1.5 py-0.5 rounded shadow-sm ${activeCropId === crop.id ? 'bg-indigo-600 text-white' : 'bg-emerald-500 text-white'}`}>#{cropRegions.indexOf(crop) + 1}</span></div>
                              </div>
                          ))}
                          {isDrawing && currentRect && <div className="absolute border-2 border-dashed border-indigo-500 bg-indigo-500/5 z-30 pointer-events-none" style={{ left: `${currentRect.x}%`, top: `${currentRect.y}%`, width: `${currentRect.w}%`, height: `${currentRect.h}%` }}></div>}
                      </div>
                  </div>
               </div>
            )}

            {viewMode === 'detail' && (
              <div className="h-full flex flex-col lg:flex-row overflow-hidden animate-fadeIn relative" key={selectedCardData?.id || 'empty'}>
                 {isLoadingDetail && (
                   <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] z-[90] flex items-center justify-center animate-fadeIn">
                     <div className="flex flex-col items-center gap-4">
                       <div className="w-12 h-12 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
                     </div>
                   </div>
                 )}

                 {selectedCardData ? (
                   <>
                     <div className={`relative flex flex-col bg-black overflow-hidden shadow-inner ${isMobile ? 'h-[40vh] shrink-0' : 'w-[45%] h-full border-r border-slate-800'}`}>
                        {isMobile && <button onClick={() => setViewMode('file')} className="absolute top-4 left-4 z-[70] w-9 h-9 bg-black/40 backdrop-blur-md rounded-xl flex items-center justify-center text-white border border-white/10 transition-colors hover:bg-black/60"><i className="fa-solid fa-chevron-left"></i></button>}
                        <div className="absolute top-4 right-4 z-[70] flex gap-2">
                          <button onClick={() => setRotation(r => r + 90)} className="w-9 h-9 bg-black/40 backdrop-blur-md rounded-xl flex items-center justify-center text-white border border-white/10 transition-colors hover:bg-black/60"><i className="fa-solid fa-rotate-right"></i></button>
                          <button onClick={() => setIsImageZoomed(true)} className="w-9 h-9 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-500/30 transition-transform active:scale-95"><i className="fa-solid fa-expand"></i></button>
                        </div>
                        <div ref={imgContainerRef} className="flex-1 w-full h-full relative overflow-hidden p-4">
                          {selectedCardData.imageUrl && containerDim.w > 0 && (
                            <img 
                              src={selectedCardData.imageUrl} 
                              className="shadow-2xl transition-transform duration-300 ease-out cursor-zoom-in" 
                              style={{ 
                                position: 'absolute', 
                                left: '50%', 
                                top: '50%', 
                                transform: `translate(-50%, -50%) rotate(${rotation}deg)`, 
                                maxWidth: (Math.abs(rotation) % 180 === 90) ? containerDim.h : containerDim.w, 
                                maxHeight: (Math.abs(rotation) % 180 === 90) ? containerDim.w : containerDim.h, 
                                objectFit: 'contain' 
                              }} 
                              onClick={() => setIsImageZoomed(true)} 
                            />
                          )}
                        </div>
                     </div>
                     <div className="flex-1 overflow-y-auto custom-scrollbar bg-white p-5 lg:p-12 space-y-6">
                          <header className="border-b border-slate-100 pb-6">
                            <div className="flex items-center justify-between mb-3">
                              <span className="px-2.5 py-1 bg-indigo-50 text-indigo-600 text-[10px] font-bold uppercase rounded-md inline-block">{selectedCardData.category}</span>
                              <div className="flex items-center gap-2">
                                <div className="flex items-center bg-slate-100 rounded-lg p-0.5 mr-2">
                                  <button onClick={handlePrevCard} disabled={currentCardIndex <= 0} className="w-7 h-7 flex items-center justify-center text-slate-500 hover:text-slate-800 disabled:opacity-30 disabled:hover:text-slate-500"><i className="fa-solid fa-chevron-left text-xs"></i></button>
                                  <div className="w-px h-3 bg-slate-300 mx-0.5"></div>
                                  <button onClick={handleNextCard} disabled={currentCardIndex === -1 || currentCardIndex >= visibleCards.length - 1} className="w-7 h-7 flex items-center justify-center text-slate-500 hover:text-slate-800 disabled:opacity-30 disabled:hover:text-slate-500"><i className="fa-solid fa-chevron-right text-xs"></i></button>
                                </div>
                                <button onClick={(e) => handleDeleteCard(e, selectedCardData.id)} className="text-[10px] font-bold text-red-400 hover:text-red-600 uppercase tracking-widest flex items-center gap-1.5 px-3 py-1 hover:bg-red-50 rounded-lg transition-colors"><i className="fa-solid fa-trash-can"></i></button>
                              </div>
                            </div>
                            <h1 className="text-2xl font-extrabold text-slate-900 leading-tight mb-2 truncate">
                              {selectedCardData.prefix && <span className="text-slate-400 font-medium text-lg mr-2">{selectedCardData.prefix}</span>}
                              {selectedCardData.firstName} {selectedCardData.lastName}
                            </h1>
                            {selectedCardData.title && <div className="text-base font-semibold text-indigo-600">{selectedCardData.title}</div>}
