    </div>
  );
});

const CompactTab = React.memo(({ label, active, count, onClick }: any) => (
  <button onClick={onClick} className={`flex-1 py-1.5 px-1 rounded-lg transition-all flex flex-col items-center justify-center min-w-0 active:scale-95 ${active ? 'bg-white text-indigo-700 shadow-sm ring-1 ring-black/5' : 'text-slate-500 hover:bg-slate-200/50'}`}>
